// ============================================================================
// Validate Input — Code node (no creds). Accepts an uploaded PDF/image (base64),
// checks type/size, and builds the Gemini Vision extraction request.
// ============================================================================

const cfg = $('Config').first().json;
const wh = $('Upload Webhook').first().json;
const body = (wh && wh.body) ? wh.body : {};

const filename = String(body.filename || 'document');
let data = String(body.data || '');
let mt = String(body.mimeType || '').toLowerCase();

// Accept a data URL too: data:application/pdf;base64,xxxx
const m = data.match(/^data:([^;]+);base64,(.*)$/s);
if (m) { if (!mt) mt = m[1].toLowerCase(); data = m[2]; }
data = data.trim();

const okType = /^(application\/pdf|image\/(png|jpe?g|webp|heic|heif))$/.test(mt);

let valid = true; let reason = '';
if (!data) { valid = false; reason = 'No file data received.'; }
else if (!okType) { valid = false; reason = 'Unsupported file type (' + (mt || 'unknown') + '). Please upload a PDF or image.'; }
else if (data.length > 18 * 1024 * 1024) { valid = false; reason = 'File too large (max ~13 MB).'; }

const prompt = 'You are an accounts-payable assistant for ' + cfg.companyName + '. '
  + 'Extract this invoice/receipt into JSON. Read EVERY line item. '
  + 'Amounts must be plain numbers (no currency symbols or commas). Dates as YYYY-MM-DD. '
  + 'currency = ISO code (e.g. USD). category = a short expense category (e.g. HVAC parts, Plumbing supplies, Electrical, Tools, Services). '
  + 'If a field is missing or unreadable, use "" for text and 0 for numbers. '
  + 'confidence = your overall 0-100 confidence in the extraction. notes = anything ambiguous or unreadable.';

const geminiBody = {
  contents: [{ role: 'user', parts: [
    { inlineData: { mimeType: mt, data } },
    { text: prompt },
  ] }],
  generationConfig: {
    temperature: 0.1,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        vendor: { type: 'STRING' },
        invoiceNumber: { type: 'STRING' },
        invoiceDate: { type: 'STRING' },
        dueDate: { type: 'STRING' },
        currency: { type: 'STRING' },
        subtotal: { type: 'NUMBER' },
        tax: { type: 'NUMBER' },
        total: { type: 'NUMBER' },
        category: { type: 'STRING' },
        lineItems: {
          type: 'ARRAY',
          items: {
            type: 'OBJECT',
            properties: {
              description: { type: 'STRING' },
              qty: { type: 'NUMBER' },
              unitPrice: { type: 'NUMBER' },
              amount: { type: 'NUMBER' },
            },
            required: ['description', 'amount'],
          },
        },
        confidence: { type: 'NUMBER' },
        notes: { type: 'STRING' },
      },
      required: ['vendor', 'total', 'lineItems', 'confidence'],
    },
  },
};

return [{ json: { valid, reason, filename, mimeType: mt, geminiBody } }];

// ============================================================================
// Map & Validate — Code node (no creds). Parses the extracted invoice, runs the
// MATH/confidence trust gate, builds the Airtable record, a dedup lookup formula,
// and a human-readable status message (used for the WhatsApp reply / response).
// ============================================================================

const cfg = $('Config').first().json;
const v = $('Validate Input').first().json;
const chat = $json; // generateContent response

let ai = {};
try { ai = JSON.parse(chat.candidates[0].content.parts.map((p) => p.text || '').join('')); } catch (e) { ai = {}; }

const num = (x) => { const n = Number(x); return Number.isFinite(n) ? n : 0; };
const vendor = (ai.vendor || '').toString().trim();
const invNo = (ai.invoiceNumber || '').toString().trim();
const subtotal = num(ai.subtotal), tax = num(ai.tax), total = num(ai.total);
const items = Array.isArray(ai.lineItems) ? ai.lineItems : [];
const conf = Math.max(0, Math.min(100, num(ai.confidence)));
const currency = (ai.currency || 'USD').toString().trim();
const invoiceDate = (ai.invoiceDate || '').toString().trim();

// ---- Trust gate: money data must add up, or a human reviews it ----
const tol = Number(cfg.mathTolerance || 0.02);
const itemsSum = items.reduce((s, it) => s + num(it.amount), 0);
const reasons = [];
if (!total) reasons.push('missing total');
if (!vendor) reasons.push('missing vendor');
const base = subtotal || total;
if (items.length && base && Math.abs(itemsSum - base) > Math.max(0.05, base * tol)) reasons.push('line items don\'t sum to subtotal');
if (subtotal && total && Math.abs((subtotal + tax) - total) > Math.max(0.05, total * tol)) reasons.push('subtotal + tax ≠ total');
if (conf && conf < Number(cfg.confidenceThreshold || 70)) reasons.push('low AI confidence (' + conf + '%)');

const status = reasons.length ? 'Needs Review' : 'OK';

const lineItemsText = items.map((it) =>
  '• ' + (it.description || 'item') + (num(it.qty) ? ' ×' + num(it.qty) : '') + (num(it.unitPrice) ? ' @ ' + num(it.unitPrice) : '') + ' = ' + num(it.amount).toFixed(2)
).join('\n');

const fields = {
  'Invoice Number': invNo,
  'Vendor': vendor,
  'Invoice Date': invoiceDate,
  'Due Date': ai.dueDate || '',
  'Subtotal': subtotal,
  'Tax': tax,
  'Total': total,
  'Currency': currency,
  'Category': ai.category || '',
  'Line Items': lineItemsText,
  'Status': status,
  'Confidence': conf / 100,
  'Review Notes': ([reasons.join('; '), ai.notes || ''].filter(Boolean).join(' | ')).slice(0, 1000),
  'Source File': v.filename,
  'Logged At': new Date().toISOString(),
};
if (!fields['Invoice Date']) delete fields['Invoice Date'];
if (!fields['Due Date']) delete fields['Due Date'];

// ---- Dedup key: an invoice # is the natural unique key; else vendor+total(+date) ----
const esc = (s) => String(s).replace(/["\\]/g, ' ').trim(); // formula-safe
let dedupFormula;
if (invNo) {
  dedupFormula = 'AND({Vendor}="' + esc(vendor) + '",{Invoice Number}="' + esc(invNo) + '")';
} else {
  dedupFormula = 'AND({Vendor}="' + esc(vendor) + '",{Total}=' + total + (invoiceDate ? ',{Invoice Date}="' + esc(invoiceDate) + '"' : '') + ')';
}

const money = currency + ' ' + total.toFixed(2);
const message = status === 'OK'
  ? '✅ Logged: ' + (vendor || 'invoice') + ' — ' + money + (invNo ? ' (#' + invNo + ')' : '')
  : '⚠️ Needs review: ' + (vendor || 'invoice') + ' — ' + money + '\nWhy: ' + reasons.join('; ');

return [{ json: {
  status, vendor, invoiceNumber: invNo, total, currency, dueDate: ai.dueDate || '', itemCount: items.length, confidence: conf, reasons,
  airtableBody: { fields, typecast: true },
  dedupFormula,
  message,
} }];

// ============================================================================
// Check Dup — Code node (no creds). Reads the Airtable dedup lookup result; if a
// matching record already exists, marks this one as a duplicate (to be rejected).
// ============================================================================

const dq = $json; // dedup query (Airtable list) response
const mv = $('Map & Validate').first().json;

const records = (dq && Array.isArray(dq.records)) ? dq.records : [];
const duplicate = records.length > 0;

const out = Object.assign({}, mv, {
  duplicate,
  dupRecordId: duplicate ? records[0].id : '',
});

if (duplicate) {
  out.message = '🔁 Duplicate — this invoice is already logged ('
    + (mv.vendor || 'vendor') + (mv.invoiceNumber ? ' #' + mv.invoiceNumber : '') + '). Skipped.';
  out.status = 'Duplicate';
}

return [{ json: out }];
